from _lib import *
lesson("advanced-relative-clauses", "Zdania względne", "Zaawansowane zdania względne: whereby, of which, prepositions", 9,
 "Na poziomie C1 zdania względne wykraczają poza who/which/that. Ważne konstrukcje: przyimek przed zaimkiem (the person to whom I spoke), kwantyfikatory z of whom/of which (some of whom, most of which, none of which), whose dla rzeczy (a company whose profits fell), whereby (dzięki któremu, w ramach którego), which odnoszące się do całego zdania (He failed, which surprised everyone) oraz zdania względne skrócone.",
 "Pozwalają tworzyć długie, precyzyjne zdania w stylu formalnym – typowe dla raportów, esejów i tekstów Reading. W Open cloze często brakuje właśnie whom, whose, which lub whereby.",
 dict(scheme="rzeczownik + (przyimek) + who/whom/which/whose/whereby + zdanie  |  kwantyfikator + of whom/of which", word_order="The candidates, all of whom were qualified… / a system whereby users pay monthly",
      affirmative=["The scientist to whom the prize was awarded is Polish.", "He has three sisters, two of whom live abroad.", "They introduced a scheme whereby staff can work from home."],
      negative=["The books, none of which I had read, were on the list.", "It's a problem about which little is known."],
      questions=["To whom should I address the letter?", "Which is the town in which you grew up?"]),
 [X("The woman to whom I was speaking is the director.", "Kobieta, z którą rozmawiałem, to dyrektorka.", "Przyimek przed whom – formalne."),
  X("The woman I was speaking to is the director.", "Kobieta, z którą rozmawiałem, to dyrektorka.", "Wersja nieformalna – przyimek na końcu, bez zaimka."),
  X("I have two brothers, both of whom are doctors.", "Mam dwóch braci; obaj są lekarzami.", "both of whom – nie both of them w zdaniu względnym."),
  X("She gave me several suggestions, most of which were useful.", "Dała mi kilka sugestii, z których większość była przydatna.", "most of which dla rzeczy."),
  X("It was a decision whose consequences nobody foresaw.", "Była to decyzja, której konsekwencji nikt nie przewidział.", "Whose także dla rzeczy."),
  X("The bank introduced a system whereby customers can pay by phone.", "Bank wprowadził system, dzięki któremu klienci mogą płacić telefonem.", "Whereby = by which / through which."),
  X("He lost his job, which came as a shock.", "Stracił pracę, co było szokiem.", "Which = co (odnosi się do całego zdania)."),
  X("This is the reason why I resigned.", "To jest powód, dla którego zrezygnowałem.", "Reason why/that."),
  X("2008 was the year in which the crisis began.", "2008 to rok, w którym zaczął się kryzys.", "In which = when (formalnie)."),
  X("The extent to which this affects children is unclear.", "Nie jest jasne, w jakim stopniu wpływa to na dzieci.", "The extent to which – bardzo częste w esejach."),
  X("The village, the name of which I have forgotten, was beautiful.", "Wioska, której nazwy zapomniałem, była piękna.", "The name of which = whose name.")],
 [C("who vs whom", "Who – podmiot lub nieformalne dopełnienie; whom – dopełnienie, zawsze po przyimku.", "To whom (nie: to who)."),
  C("which vs that", "That tylko w zdaniach definiujących, nie po przecinku i nie po przyimku.", "The book, which I liked… (nie: , that I liked)."),
  C("whereby vs where", "Where – miejsce; whereby – sposób/mechanizm.", "A scheme whereby… (nie: a scheme where w stylu formalnym).")],
 [W("I have two sisters, both of them live in Gdańsk.", "I have two sisters, both of whom live in Gdańsk.", "Bez zaimka względnego powstaje comma splice."),
  W("The man to who I spoke was rude.", "The man to whom I spoke was rude.", "Po przyimku – whom."),
  W("My car, that is ten years old, still works.", "My car, which is ten years old, still works.", "That nie stoi po przecinku."),
  W("The house in which I live in is old.", "The house in which I live is old.", "Przyimek tylko raz.")],
 ["Phrasal verbs nie rozdzielamy: the problem which we came across (nie: across which we came).",
  "W zdaniach niedefiniujących nie można pominąć zaimka.",
  "Whose można zastąpić 'of which' tylko dla rzeczy: the house, the roof of which…"],
 [dict(en="The study, the findings of which were published last month, challenges previous assumptions.", pl="Badanie, którego wyniki opublikowano w zeszłym miesiącu, podważa wcześniejsze założenia.", note="Bardzo formalna struktura."),
  dict(en="There are many ways in which technology can support learning.", pl="Istnieje wiele sposobów, w jakie technologia może wspierać naukę.", note="Ways in which – zamiast 'ways how' (błąd)."),
  dict(en="The council should adopt a policy whereby new buildings must be energy-efficient.", pl="Rada powinna przyjąć politykę, zgodnie z którą nowe budynki muszą być energooszczędne.", note="Do propozycji/raportu.")],
 [G("The person to ___ this letter is addressed has moved.", ["whom"], "Po przyimku – whom."),
  G("I bought ten apples, half of ___ were rotten.", ["which"], "Rzeczy → of which."),
  G("She is an author ___ books have been translated into 40 languages.", ["whose"], "Przynależność → whose."),
  M("They set up a scheme ___ volunteers could help elderly neighbours.", ["whereby", "where", "which", "what"], "whereby", "Mechanizm → whereby.", {"where": "Where odnosi się do miejsca.", "which": "Brakuje przyimka (by which).", "what": "What nie jest zaimkiem względnym po rzeczowniku."}),
  G("He missed the final, ___ annoyed his coach.", ["which"], "Which odnosi się do całego zdania."),
  K("I met several students and they were all from Spain.", "WHOM", "I met several students, all ___ from Spain.", ["of whom were"], "all of whom."),
  K("We don't know how far this policy will help.", "EXTENT", "We don't know the ___ this policy will help.", ["extent to which"], "The extent to which."),
  E("My grandparents, both of them are over 90, live with us.", ["My grandparents, both of whom are over 90, live with us.", "both of whom"], "both of whom.")],
 [G("The hotel at ___ we stayed was excellent.", ["which"], "Przyimek + which."),
  G("There are two candidates, neither of ___ has experience.", ["whom"], "Ludzie → of whom."),
  K("The company's profits have doubled. It is based in Poznań.", "WHOSE", "The company, ___ doubled, is based in Poznań.", ["whose profits have"], "whose + rzeczownik."),
  M("This is the town ___ I was born.", ["in which", "which", "in that", "whom"], "in which", "Miejsce: in which (= where).", {"which": "Brakuje przyimka in.", "in that": "That nie występuje po przyimku.", "whom": "Whom odnosi się do ludzi."}),
  G("She told me a story, most of ___ I didn't believe.", ["which"], "most of which."),
  T("Mam wielu przyjaciół, z których większość mieszka w Warszawie.", ["I have many friends, most of whom live in Warsaw.", "I have a lot of friends, most of whom live in Warsaw."], "most of whom.")])
